import { startLogin } from "@/const";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";
import { ArrowRight, Check, CircleHelp, LockKeyhole, Sparkles } from "lucide-react";
import { Link, useLocation, useRoute } from "wouter";
import { useEffect, useMemo, useState } from "react";

const stages = [
  { key: "memory", label: "Memory", note: "Your private beginning" },
  { key: "essence", label: "Essence", note: "What feels true" },
  { key: "story", label: "Story", note: "Meaning before materials" },
  { key: "florals", label: "Florals", note: "Choose by role" },
  { key: "recipe", label: "Recipe", note: "Lock a truthful snapshot" },
  { key: "blueprint", label: "Blueprint", note: "Read the hierarchy" },
  { key: "wreath", label: "Wreath", note: "Review a render package" },
  { key: "outcome", label: "Outcome", note: "Comes later" },
] as const;

type StageKey = (typeof stages)[number]["key"];
type FloralRole = "PRIMARY_FOCAL" | "SUPPORTING_FLORAL" | "DIRECTIONAL_ACCENT" | "GREENERY_MOVEMENT";

const roleTitles: Record<FloralRole, { title: string; instruction: string }> = {
  PRIMARY_FOCAL: { title: "Primary focal", instruction: "Choose one concentrated visual anchor for the emotional center." },
  SUPPORTING_FLORAL: { title: "Supporting floral", instruction: "Choose a companion that frames the focal presence without competing with it." },
  DIRECTIONAL_ACCENT: { title: "Directional accent", instruction: "Choose a restrained gesture that carries movement outward." },
  GREENERY_MOVEMENT: { title: "Greenery movement", instruction: "Choose the movement field that holds the floral hierarchy in space." },
};

function parseWorkspaceId(location: string) {
  const value = Number(new URLSearchParams(location.split("?")[1] ?? "").get("workspace"));
  return Number.isInteger(value) && value > 0 ? value : undefined;
}

function StageRail({ current, viewing, onSelect }: { current: StageKey; viewing: StageKey; onSelect: (stage: StageKey) => void }) {
  const currentIndex = stages.findIndex(stage => stage.key === current);
  return <ol className="grid gap-2 sm:grid-cols-2 lg:grid-cols-8" aria-label="Wreath Creation progress">
    {stages.map((stage, index) => {
      const complete = index < currentIndex;
      const active = stage.key === viewing;
      return <li key={stage.key}><button type="button" onClick={() => onSelect(stage.key)} className={`min-h-20 w-full rounded-2xl border px-3 py-3 text-left transition ${active ? "border-[#50645B] bg-[#E9EFEA]" : complete ? "border-[#C9D6CB] bg-[#F6F3EE]" : "border-[#DED7CC] bg-white hover:border-[#BEB3A4]"}`}><span className="flex items-center justify-between text-[10px] font-semibold uppercase tracking-[.14em] text-[#6B5A4A]">{String(index + 1).padStart(2, "0")}{complete ? <Check className="h-3.5 w-3.5 text-[#50645B]" /> : null}</span><span className="mt-2 block font-serif text-lg text-[#23211F]">{stage.label}</span><span className="mt-1 block text-[11px] leading-4 text-[#70685F]">{stage.note}</span></button></li>;
    })}
  </ol>;
}

function LockedStage({ stage }: { stage: "outcome" }) {
  const message = "Commission, purchase, saving, and Lookbook paths are intentionally unavailable until approved design and commercial policy exist.";
  return <section className="rounded-3xl border border-dashed border-[#BEB3A4] bg-[#FFFEFB] p-7 sm:p-10"><span className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">{stage} · dependency gated</span><h2 className="mt-4 font-serif text-4xl tracking-[-.035em] text-[#23211F]">This chapter waits for the work that makes it true.</h2><p className="mt-5 max-w-2xl text-base leading-7 text-[#5E564E]">{message}</p><div className="mt-8 flex items-start gap-3 rounded-2xl bg-[#F0ECE5] p-4 text-sm leading-6 text-[#5E564E]"><LockKeyhole className="mt-0.5 h-4 w-4 shrink-0 text-[#50645B]" />No commission, purchase, published outcome, or Lookbook action is configured here.</div></section>;
}

function FloralStage({ florals, storyApproved, workspaceId, projectId, generate, select }: { florals: any; storyApproved: boolean; workspaceId: number; projectId: number; generate: any; select: any }) {
  const roleSet = florals?.roleSet;
  const candidates = florals?.candidates ?? [];
  const tray = florals?.tray ?? [];
  const selected = new Map(tray.map((row: any) => [row.selection.role, row.selection.candidateId]));
  const checks = florals?.compatibility?.checks ?? [];

  if (!storyApproved) return <section className="rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-7 sm:p-10"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">04 · Guided Florals</p><h2 className="mt-4 font-serif text-4xl tracking-[-.04em]">Your approved Story comes first.</h2><p className="mt-4 text-[#5E564E]">Guided Florals only opens after you approve the Memory Story. It offers reference families by role, never an invented inventory or a recipe.</p></section>;
  if (!roleSet) return <section className="rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-7 sm:p-10"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">04 · Guided Florals</p><h2 className="mt-4 font-serif text-4xl tracking-[-.04em]">Choose material identity by role, not by pressure.</h2><p className="mt-4 max-w-2xl text-base leading-7 text-[#5E564E]">We show a small source-versioned reference catalog. No SKU, vendor, stock, price, or purchase availability appears here.</p><Button disabled={generate.isPending} onClick={() => generate.mutate({ workspaceId, projectId })} className="mt-7 h-12 rounded-full bg-[#23211F] px-6 text-white hover:bg-[#50645B]">{generate.isPending ? "Opening Guided Florals…" : "Open Guided Florals"}<ArrowRight className="ml-2 h-4 w-4" /></Button>{generate.error ? <p role="alert" className="mt-4 text-sm text-red-700">{generate.error.message}</p> : null}</section>;

  return <section className="space-y-6"><div className="rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-6 sm:p-9"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">04 · Guided Florals</p><h2 className="mt-4 font-serif text-4xl tracking-[-.04em]">Choose each visual role with intention.</h2><p className="mt-4 max-w-3xl text-base leading-7 text-[#5E564E]">Every option is a source-versioned reference family. It explains why it may fit this role but does not claim availability, quantity, price, or a finished Recipe.</p></div>{(Object.keys(roleTitles) as FloralRole[]).map(role => <section key={role} className="rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-5 sm:p-7"><div><p className="text-xs font-semibold uppercase tracking-[.14em] text-[#6B5A4A]">{roleTitles[role].title}</p><p className="mt-2 text-sm leading-6 text-[#5E564E]">{roleTitles[role].instruction}</p></div><div className="mt-5 grid gap-3 lg:grid-cols-3">{candidates.filter((row: any) => row.candidate.role === role).map((row: any) => { const isSelected = selected.get(role) === row.candidate.id; return <article key={row.candidate.id} className={`rounded-2xl border p-4 ${isSelected ? "border-[#50645B] bg-[#F2F6F2]" : "border-[#E3DDD3] bg-white"}`}><p className="font-serif text-2xl text-[#23211F]">{row.catalog.commonName}</p><p className="mt-1 text-xs uppercase tracking-[.12em] text-[#6B5A4A]">Reference family · option {row.candidate.rank}</p><p className="mt-4 text-sm leading-6 text-[#5E564E]">{row.candidate.explanation}</p><p className="mt-3 text-xs leading-5 text-[#70685F]">Why it appears: {(row.candidate.matchEvidence ?? []).join(" · ")}</p>{row.candidate.tensionNotes?.length ? <p className="mt-2 text-xs leading-5 text-[#8A4B27]">{row.candidate.tensionNotes.join(" ")}</p> : null}<Button disabled={select.isPending || isSelected} onClick={() => select.mutate({ workspaceId, projectId, roleSetId: roleSet.id, candidateId: row.candidate.id })} variant={isSelected ? "outline" : "default"} className={`mt-5 h-10 rounded-full px-4 ${isSelected ? "border-[#50645B] bg-transparent text-[#405C4C]" : "bg-[#23211F] text-white hover:bg-[#50645B]"}`}>{isSelected ? "In My Wreath Tray" : "Choose this role"}{isSelected ? <Check className="ml-2 h-4 w-4" /> : null}</Button></article>; })}</div></section>)}<section className="rounded-[2rem] border border-[#D6D0C5] bg-[#F7F4EE] p-6 sm:p-8"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">My Wreath Tray</p><h2 className="mt-3 font-serif text-3xl tracking-[-.035em]">A saved role map, not a Recipe.</h2><div className="mt-5 grid gap-3 sm:grid-cols-2">{tray.map((row: any) => <div key={row.selection.id} className="rounded-2xl bg-white p-4"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#6B5A4A]">{roleTitles[row.selection.role as FloralRole].title}</p><p className="mt-2 font-serif text-xl text-[#23211F]">{row.catalog.commonName}</p><p className="mt-1 text-xs leading-5 text-[#70685F]">Reference family only · no inventory commitment</p></div>)}</div><div className="mt-6 space-y-2 border-t border-[#DED7CC] pt-5">{checks.map((check: any) => <p key={check.key} className={`rounded-xl px-3 py-2 text-sm leading-6 ${check.status === "pass" ? "bg-[#E9EFEA] text-[#405C4C]" : check.status === "warning" ? "bg-[#FFF8ED] text-[#7B4A22]" : "bg-[#F0ECE5] text-[#5E564E]"}`}>{check.message}</p>)}</div>{select.error ? <p role="alert" className="mt-4 text-sm text-red-700">{select.error.message}</p> : null}</section></section>;
}

function RecipeStage({ florals, recipeData, workspaceId, projectId, lock, onBlueprint }: { florals: any; recipeData: any; workspaceId: number; projectId: number; lock: any; onBlueprint: () => void }) {
  const recipe = recipeData?.recipe;
  const items = recipeData?.items ?? [];
  const canLock = Boolean(florals?.roleSet && florals?.compatibility?.outcome === "pass");
  if (recipe?.status === "stale") return <section className="rounded-[2rem] border border-[#D8BDA4] bg-[#FFF8ED] p-7 sm:p-10"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#8A4B27]">05 · Recipe revision needed</p><h2 className="mt-4 font-serif text-4xl tracking-[-.04em]">A saved selection changed after this Recipe was locked.</h2><p className="mt-4 text-base leading-7 text-[#7B4A22]">{recipe.staleReason ?? "Return to Guided Florals, review your current Tray, and lock a new Recipe from a passing snapshot."}</p></section>;
  if (recipe?.status === "locked") return <section className="space-y-6"><div className="rounded-[2rem] border border-[#C9D6CB] bg-[#F4F8F4] p-7 sm:p-10"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#405C4C]">05 · Recipe locked</p><h2 className="mt-4 font-serif text-4xl tracking-[-.04em]">A truthful snapshot of your Wreath Tray.</h2><p className="mt-4 text-base leading-7 text-[#405C4C]">Recipe v{recipe.version} preserves the selected reference families and roles. It does not reserve inventory, set quantities, price materials, or create a build instruction.</p></div><div className="grid gap-4 sm:grid-cols-2">{items.map((row: any) => <article key={row.item.id} className="rounded-2xl border border-[#DED7CC] bg-[#FFFEFB] p-5"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#6B5A4A]">{roleTitles[row.item.role as FloralRole].title}</p><h3 className="mt-3 font-serif text-2xl text-[#23211F]">{row.item.commonNameSnapshot}</h3><p className="mt-2 text-sm leading-6 text-[#5E564E]">Reference family retained from your locked Tray.</p></article>)}</div><Button onClick={onBlueprint} className="h-11 rounded-full bg-[#23211F] px-5 text-white hover:bg-[#50645B]">Review Blueprint <ArrowRight className="ml-2 h-4 w-4" /></Button></section>;
  return <section className="rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-7 sm:p-10"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">05 · Recipe</p><h2 className="mt-4 font-serif text-4xl tracking-[-.04em]">Lock only what your Tray can support.</h2><p className="mt-4 max-w-3xl text-base leading-7 text-[#5E564E]">A Recipe creates an immutable version of a passing four-role Tray. Compatibility warnings or missing roles keep this action unavailable; this action does not reserve, order, price, or substitute materials.</p><div className={`mt-7 rounded-2xl p-5 text-sm leading-6 ${canLock ? "bg-[#E9EFEA] text-[#405C4C]" : "bg-[#F2EEE7] text-[#5E564E]"}`}>{canLock ? "Your current Tray has a passing compatibility state and can be locked as a versioned Recipe." : "Return to Guided Florals and resolve every required role and compatibility note before Recipe lock."}</div><Button disabled={!canLock || lock.isPending} onClick={() => lock.mutate({ workspaceId, projectId })} className="mt-7 h-12 rounded-full bg-[#23211F] px-6 text-white hover:bg-[#50645B]">{lock.isPending ? "Locking Recipe…" : "Lock this Recipe"}<Check className="ml-2 h-4 w-4" /></Button>{lock.error ? <p role="alert" className="mt-4 text-sm text-red-700">{lock.error.message}</p> : null}</section>;
}

function BlueprintStage({ recipeData, workspaceId, projectId, generate }: { recipeData: any; workspaceId: number; projectId: number; generate: any }) {
  const recipe = recipeData?.recipe;
  const blueprint = recipeData?.blueprint;
  if (!recipe || recipe.status !== "locked") return <section className="rounded-[2rem] border border-dashed border-[#BEB3A4] bg-[#FFFEFB] p-7 sm:p-10"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">06 · Blueprint · dependency gated</p><h2 className="mt-4 font-serif text-4xl tracking-[-.04em]">A current locked Recipe comes first.</h2><p className="mt-4 max-w-2xl text-base leading-7 text-[#5E564E]">The Blueprint can only derive from a non-stale Recipe. It remains unavailable until the Tray is complete, compatible, and locked.</p></section>;
  if (blueprint?.status === "stale") return <section className="rounded-[2rem] border border-[#D8BDA4] bg-[#FFF8ED] p-7 sm:p-10"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#8A4B27]">06 · Blueprint revision needed</p><h2 className="mt-4 font-serif text-4xl tracking-[-.04em]">This Blueprint belongs to a Recipe that is no longer current.</h2><p className="mt-4 text-base leading-7 text-[#7B4A22]">{blueprint.staleReason ?? "Return to the current Tray, lock a new Recipe, then derive a new Blueprint."}</p></section>;
  if (!blueprint) return <section className="rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-7 sm:p-10"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">06 · Simplified Blueprint</p><h2 className="mt-4 font-serif text-4xl tracking-[-.04em]">See the hierarchy your locked Recipe holds.</h2><p className="mt-4 max-w-3xl text-base leading-7 text-[#5E564E]">This compilation is deterministic and versioned. It reads the locked Recipe only; it cannot add flowers, choose inventory, calculate quantities, or create geometry or a render.</p><Button disabled={generate.isPending} onClick={() => generate.mutate({ workspaceId, projectId })} className="mt-7 h-12 rounded-full bg-[#23211F] px-6 text-white hover:bg-[#50645B]">{generate.isPending ? "Deriving Blueprint…" : "Generate simplified Blueprint"}<ArrowRight className="ml-2 h-4 w-4" /></Button>{generate.error ? <p role="alert" className="mt-4 text-sm text-red-700">{generate.error.message}</p> : null}</section>;
  const hierarchy = (blueprint.hierarchy ?? []) as Array<{ role: FloralRole; commonName: string; description: string }>;
  return <section className="space-y-6"><div className="rounded-[2rem] border border-[#C9D6CB] bg-[#F4F8F4] p-7 sm:p-10"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#405C4C]">06 · Simplified Blueprint ready</p><h2 className="mt-4 font-serif text-4xl tracking-[-.04em]">A readable hierarchy, before any construction claim.</h2><p className="mt-4 text-base leading-7 text-[#405C4C]">Blueprint v{blueprint.version} preserves the role order from your locked Recipe. Its scope stops before quantity, placement geometry, inventory, rendering, or production instructions.</p></div><div className="grid gap-4 sm:grid-cols-2">{hierarchy.map(item => <article key={item.role} className="rounded-2xl border border-[#DED7CC] bg-[#FFFEFB] p-5"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#6B5A4A]">{roleTitles[item.role].title}</p><h3 className="mt-3 font-serif text-2xl text-[#23211F]">{item.commonName}</h3><p className="mt-2 text-sm leading-6 text-[#5E564E]">{item.description}</p></article>)}</div><div className="rounded-2xl bg-[#F2EEE7] p-5"><p className="text-xs font-semibold uppercase tracking-[.14em] text-[#6B5A4A]">Provenance and boundary</p>{(blueprint.derivationNotes ?? []).map((note: string) => <p key={note} className="mt-2 text-sm leading-6 text-[#5E564E]">{note}</p>)}</div></section>;
}

function RenderPackageStage({ recipeData, renderData, workspaceId, projectId, prepare, approve, requestHandoff, handoffNote, setHandoffNote }: { recipeData: any; renderData: any; workspaceId: number; projectId: number; prepare: any; approve: any; requestHandoff: any; handoffNote: string; setHandoffNote: (value: string) => void }) {
  const recipe = recipeData?.recipe;
  const blueprint = recipeData?.blueprint;
  const renderPackage = renderData?.renderPackage;
  const handoff = renderData?.handoff;
  if (!recipe || recipe.status !== "locked" || !blueprint || blueprint.status !== "ready") return <section className="rounded-[2rem] border border-dashed border-[#BEB3A4] bg-[#FFFEFB] p-7 sm:p-10"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">07 · Wreath · dependency gated</p><h2 className="mt-4 font-serif text-4xl tracking-[-.04em]">A current Recipe and ready Blueprint come first.</h2><p className="mt-4 max-w-2xl text-base leading-7 text-[#5E564E]">The render package only compiles the locked role snapshot and simplified hierarchy once both are current. It cannot produce an image or initiate provider work.</p></section>;
  if (renderPackage?.status === "stale") return <section className="rounded-[2rem] border border-[#D8BDA4] bg-[#FFF8ED] p-7 sm:p-10"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#8A4B27]">07 · Render package revision needed</p><h2 className="mt-4 font-serif text-4xl tracking-[-.04em]">A source selection changed after this package was prepared.</h2><p className="mt-4 max-w-2xl text-base leading-7 text-[#7B4A22]">{renderPackage.staleReason ?? "Return to Guided Florals, lock a current Recipe, generate a Blueprint, then prepare a new render package."}</p><div className="mt-7 rounded-2xl bg-[#F4E8D9] p-4 text-sm leading-6 text-[#7B4A22]">The earlier package and any handoff record remain stale history. Nothing was sent to a provider or rendered automatically.</div></section>;
  if (!renderPackage) return <section className="rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-7 sm:p-10"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">07 · Render package</p><h2 className="mt-4 font-serif text-4xl tracking-[-.04em]">Prepare an exact handoff brief for review.</h2><p className="mt-4 max-w-3xl text-base leading-7 text-[#5E564E]">This deterministic package records Recipe v{recipe.version}, Blueprint v{blueprint.version}, the approved role hierarchy, a renderer rule, and explicit exclusions. It is a provenance manifest—not a renderer, image request, material reservation, charge, or publication.</p><Button disabled={prepare.isPending} onClick={() => prepare.mutate({ workspaceId, projectId })} className="mt-7 h-12 rounded-full bg-[#23211F] px-6 text-white hover:bg-[#50645B]">{prepare.isPending ? "Preparing package…" : "Prepare render package"}<ArrowRight className="ml-2 h-4 w-4" /></Button>{prepare.error ? <p role="alert" className="mt-4 text-sm text-red-700">{prepare.error.message}</p> : null}</section>;
  const manifest = renderPackage.manifest as { contractVersion?: string; selectedRoles?: Array<{ role: FloralRole; commonName: string; selectionRationale?: string | null }>; rendererRule?: string; exclusions?: string[] };
  return <section className="space-y-6"><div className={`rounded-[2rem] border p-7 sm:p-10 ${renderPackage.status === "approved" ? "border-[#C9D6CB] bg-[#F4F8F4]" : "border-[#DED7CC] bg-[#FFFEFB]"}`}><p className={`text-xs font-semibold uppercase tracking-[.16em] ${renderPackage.status === "approved" ? "text-[#405C4C]" : "text-[#6B5A4A]"}`}>07 · Render package v{renderPackage.version} · {renderPackage.status}</p><h2 className="mt-4 font-serif text-4xl tracking-[-.04em]">Review a bounded render instruction.</h2><p className="mt-4 max-w-3xl text-base leading-7 text-[#5E564E]">Contract: {manifest.contractVersion ?? "evercrafted_render_package_v1"}. This package is derived from locked Recipe v{recipe.version} and ready Blueprint v{blueprint.version}; it cannot silently redesign or enrich those sources.</p></div><div className="grid gap-5 lg:grid-cols-[1.15fr_.85fr]"><section className="rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-6"><p className="text-xs font-semibold uppercase tracking-[.14em] text-[#6B5A4A]">Role hierarchy</p><div className="mt-5 space-y-3">{(manifest.selectedRoles ?? []).map(item => <div key={item.role} className="rounded-2xl bg-[#F7F4EE] p-4"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#6B5A4A]">{roleTitles[item.role].title}</p><p className="mt-2 font-serif text-2xl text-[#23211F]">{item.commonName}</p><p className="mt-2 text-sm leading-6 text-[#5E564E]">{item.selectionRationale ?? "Retained from the locked role snapshot."}</p></div>)}</div></section><section className="rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-6"><p className="text-xs font-semibold uppercase tracking-[.14em] text-[#6B5A4A]">Renderer rule</p><p className="mt-4 font-serif text-2xl leading-8 text-[#23211F]">{manifest.rendererRule}</p><p className="mt-7 text-xs font-semibold uppercase tracking-[.14em] text-[#6B5A4A]">Explicit exclusions</p><div className="mt-4 flex flex-wrap gap-2">{(manifest.exclusions ?? []).map(exclusion => <span key={exclusion} className="rounded-full bg-[#F2EEE7] px-3 py-1.5 text-xs text-[#5E564E]">{exclusion.replace(/_/g, " ")}</span>)}</div></section></div>{renderPackage.status === "draft" ? <section className="rounded-[2rem] border border-[#DCD4C9] bg-[#F7F4EE] p-6 sm:flex sm:items-center sm:justify-between sm:gap-6"><div><p className="font-serif text-2xl text-[#23211F]">Approve this exact package before handoff.</p><p className="mt-2 max-w-2xl text-sm leading-6 text-[#5E564E]">Approval records your review of the source versions, role hierarchy, renderer rule, and exclusions. It does not render anything.</p></div><Button disabled={approve.isPending} onClick={() => approve.mutate({ workspaceId, projectId, renderPackageId: renderPackage.id })} className="mt-5 h-11 rounded-full bg-[#23211F] px-5 text-white hover:bg-[#50645B] sm:mt-0">{approve.isPending ? "Approving…" : "Approve package"}<Check className="ml-2 h-4 w-4" /></Button></section> : null}{renderPackage.status === "approved" ? <section className="rounded-[2rem] border border-[#C9D6CB] bg-[#F4F8F4] p-6"><p className="text-xs font-semibold uppercase tracking-[.14em] text-[#405C4C]">Manual provider-neutral handoff</p>{handoff ? <><h3 className="mt-3 font-serif text-3xl tracking-[-.035em] text-[#23211F]">Handoff intent recorded.</h3><p className="mt-3 max-w-3xl text-sm leading-6 text-[#405C4C]">Status: {handoff.status.replace(/_/g, " ")}. No provider is configured or called, no task is created, and no image or outcome is available from this step.</p></> : <><h3 className="mt-3 font-serif text-3xl tracking-[-.035em] text-[#23211F]">Request a future manual handoff.</h3><p className="mt-3 max-w-3xl text-sm leading-6 text-[#405C4C]">This records a provider-neutral request for later operational review. It does not transmit data, choose a provider, generate a render, charge a client, or publish an outcome.</p><label htmlFor="manual-handoff-note" className="mt-5 block text-sm font-medium text-[#23211F]">Optional review note</label><Textarea id="manual-handoff-note" value={handoffNote} onChange={event => setHandoffNote(event.target.value)} maxLength={1000} className="mt-2 min-h-24 border-[#B8C8BA] bg-white" placeholder="A short note for a future manual review…" /><Button disabled={requestHandoff.isPending} onClick={() => requestHandoff.mutate({ workspaceId, projectId, renderPackageId: renderPackage.id, requestNote: handoffNote.trim() || undefined })} className="mt-5 h-11 rounded-full bg-[#23211F] px-5 text-white hover:bg-[#50645B]">{requestHandoff.isPending ? "Recording request…" : "Request manual handoff"}<ArrowRight className="ml-2 h-4 w-4" /></Button>{requestHandoff.error ? <p role="alert" className="mt-4 text-sm text-red-700">{requestHandoff.error.message}</p> : null}</>}</section> : null}{approve.error ? <p role="alert" className="text-sm text-red-700">{approve.error.message}</p> : null}</section>;
}

function RevisionSupport({ renderData, revisionData, comparison, baselineId, setBaselineId, requestRevision, revisionReason, setRevisionReason }: { renderData: any; revisionData: any; comparison: any; baselineId?: number; setBaselineId: (value: number) => void; requestRevision: any; revisionReason: string; setRevisionReason: (value: string) => void }) {
  const renderPackage = renderData?.renderPackage;
  const handoff = renderData?.handoff;
  const history = revisionData?.history ?? [];
  const revisionRequests = revisionData?.revisionRequests ?? [];
  if (!renderPackage || renderPackage.status === "stale") return null;
  const currentRevision = revisionRequests.find((request: any) => request.renderPackageId === renderPackage.id);
  const olderPackages = history.filter((item: any) => item.id !== renderPackage.id);
  const comparedRoles = comparison.data?.roles ?? [];
  return <section className="mt-6 space-y-5 border-t border-[#DCD4C9] pt-6"><div className="rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-6 sm:p-8"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">Checkpoint F · comparison and history</p><h3 className="mt-3 font-serif text-3xl tracking-[-.035em] text-[#23211F]">See what changed, without rewriting history.</h3><p className="mt-3 max-w-3xl text-sm leading-6 text-[#5E564E]">Every package remains an immutable provenance snapshot. Comparison uses only saved source versions, role-family names, and the existing exclusions; it does not reveal inventory, geometry, a render result, provider state, price, or any Outcome path.</p><div className="mt-5 grid gap-3 sm:grid-cols-2"><div className="rounded-2xl bg-[#F7F4EE] p-4"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#6B5A4A]">Current package</p><p className="mt-2 font-serif text-2xl text-[#23211F]">v{renderPackage.version} · {renderPackage.status}</p><p className="mt-2 text-sm text-[#5E564E]">Recipe and Blueprint provenance are retained in the approved package.</p></div><div className="rounded-2xl bg-[#F7F4EE] p-4"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#6B5A4A]">History retained</p><p className="mt-2 font-serif text-2xl text-[#23211F]">{history.length} package{history.length === 1 ? "" : "s"}</p><p className="mt-2 text-sm text-[#5E564E]">Earlier or stale versions remain reviewable rather than being overwritten.</p></div></div>{olderPackages.length ? <div className="mt-6 rounded-2xl border border-[#DED7CC] bg-white p-5"><label htmlFor="render-comparison-baseline" className="text-sm font-medium text-[#23211F]">Compare with an earlier package</label><select id="render-comparison-baseline" value={baselineId ?? ""} onChange={event => setBaselineId(Number(event.target.value))} className="mt-3 h-11 w-full rounded-md border border-[#CFC5B8] bg-white px-3 text-sm"><option value="" disabled>Select a saved package</option>{olderPackages.map((item: any) => <option key={item.id} value={item.id}>Package v{item.version} · {item.status}</option>)}</select>{comparison.isLoading ? <p className="mt-4 text-sm text-[#70685F]">Comparing retained provenance…</p> : null}{comparison.error ? <p role="alert" className="mt-4 text-sm text-red-700">{comparison.error.message}</p> : null}{comparison.data ? <div className="mt-5 space-y-4"><div className="rounded-2xl bg-[#F2EEE7] p-4 text-sm leading-6 text-[#5E564E]"><p><strong className="text-[#23211F]">Source versions:</strong> Recipe {comparison.data.sourceChanges.recipeVersionChanged ? "changed" : "unchanged"} · Blueprint {comparison.data.sourceChanges.blueprintVersionChanged ? "changed" : "unchanged"}.</p><p className="mt-2">{comparison.data.boundary}</p></div><div className="grid gap-3 sm:grid-cols-2">{comparedRoles.map((role: any) => <div key={role.role} className="rounded-2xl border border-[#E3DDD3] p-4"><p className="text-[10px] font-semibold uppercase tracking-[.14em] text-[#6B5A4A]">{roleTitles[role.role as FloralRole]?.title ?? role.role}</p><p className="mt-2 text-sm text-[#5E564E]">Earlier: <strong className="text-[#23211F]">{role.baselineCommonName ?? "Not retained"}</strong></p><p className="mt-1 text-sm text-[#5E564E]">Current: <strong className="text-[#23211F]">{role.primaryCommonName ?? "Not retained"}</strong></p><p className={`mt-3 text-xs ${role.changed ? "text-[#8A4B27]" : "text-[#405C4C]"}`}>{role.changed ? "This role changed between snapshots." : "This role is unchanged between snapshots."}</p></div>)}</div></div> : null}</div> : <p className="mt-6 rounded-2xl border border-dashed border-[#D0C8BB] p-4 text-sm leading-6 text-[#70685F]">A comparison becomes available only when more than one saved package exists. This checkpoint never creates an alternative package automatically.</p>}</div>{renderPackage.status === "approved" ? <section className="rounded-[2rem] border border-[#DCD4C9] bg-[#F7F4EE] p-6 sm:p-8"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">Controlled revision</p>{currentRevision ? <><h3 className="mt-3 font-serif text-3xl tracking-[-.035em] text-[#23211F]">Revision request v{currentRevision.version} is retained.</h3><p className="mt-3 text-sm leading-6 text-[#5E564E]">{currentRevision.reason}</p><p className="mt-3 rounded-2xl bg-white p-4 text-sm leading-6 text-[#5E564E]">Status: {currentRevision.status.replace(/_/g, " ")}. The approved package remains immutable. Return to Guided Florals, Recipe, and Blueprint to make a future source-safe change; no provider, render, or Outcome action is triggered.</p></> : handoff ? <><h3 className="mt-3 font-serif text-3xl tracking-[-.035em] text-[#23211F]">This package already has a handoff intent.</h3><p className="mt-3 text-sm leading-6 text-[#5E564E]">A controlled revision is intentionally unavailable until a later workflow resolves this provider-neutral handoff record. No provider is called here.</p></> : <><h3 className="mt-3 font-serif text-3xl tracking-[-.035em] text-[#23211F]">Ask to revisit the source decisions.</h3><p className="mt-3 max-w-3xl text-sm leading-6 text-[#5E564E]">Record what no longer feels right. This preserves the approved package and blocks a manual handoff while a later source-safe revision is considered. It never edits your memory or silently substitutes a floral family.</p><label htmlFor="render-revision-reason" className="mt-5 block text-sm font-medium text-[#23211F]">What should be revisited?</label><Textarea id="render-revision-reason" value={revisionReason} onChange={event => setRevisionReason(event.target.value)} maxLength={1500} className="mt-2 min-h-24 border-[#CFC5B8] bg-white" placeholder="Describe the meaning, role relationship, or hierarchy you want to revisit…" /><Button disabled={requestRevision.isPending || revisionReason.trim().length < 10} onClick={() => requestRevision.mutate({ renderPackageId: renderPackage.id, reason: revisionReason.trim() })} className="mt-5 h-11 rounded-full bg-[#23211F] px-5 text-white hover:bg-[#50645B]">{requestRevision.isPending ? "Recording revision…" : "Request controlled revision"}<ArrowRight className="ml-2 h-4 w-4" /></Button>{requestRevision.error ? <p role="alert" className="mt-4 text-sm text-red-700">{requestRevision.error.message}</p> : null}</>}</section> : null}<section className="rounded-2xl border border-dashed border-[#BEB3A4] bg-[#FFFEFB] p-5 text-sm leading-6 text-[#5E564E]"><LockKeyhole className="mb-2 h-4 w-4 text-[#50645B]" />Outcome remains gated: no render output, purchase, commission, inventory, price, checkout, fulfilment, Lookbook, publication, Signature personalization, or derivative path is enabled by comparison or revision history.</section></section>;
}

export default function WreathCreation() {
  const { isAuthenticated, loading } = useAuth();
  const [location, navigate] = useLocation();
  const [, params] = useRoute("/create/:projectId");
  const projectId = params?.projectId ? Number(params.projectId) : undefined;
  const spaces = trpc.workspace.listMine.useQuery(undefined, { enabled: isAuthenticated });
  const workspaceId = parseWorkspaceId(location) ?? spaces.data?.[0]?.id;
  const journey = trpc.guidedWreath.journey.useQuery({ workspaceId: workspaceId ?? 0, projectId: projectId ?? 0 }, { enabled: Boolean(workspaceId && projectId) });
  const refresh = () => journey.refetch();
  const start = trpc.guidedWreath.start.useMutation({ onSuccess: project => navigate(`/create/${project.id}?workspace=${workspaceId}`) });
  const saveMemory = trpc.guidedWreath.saveMemory.useMutation({ onSuccess: refresh });
  const generateDraft = trpc.guidedWreath.generateDraft.useMutation({ onSuccess: refresh });
  const decide = trpc.guidedWreath.decide.useMutation({ onSuccess: refresh });
  const generateFlorals = trpc.guidedWreath.generateFlorals.useMutation({ onSuccess: refresh });
  const selectFloral = trpc.guidedWreath.selectFloral.useMutation({ onSuccess: refresh });
  const lockRecipe = trpc.guidedWreath.lockRecipe.useMutation({ onSuccess: refresh });
  const generateBlueprint = trpc.guidedWreath.generateBlueprint.useMutation({ onSuccess: refresh });
  const prepareRenderPackage = trpc.guidedWreath.prepareRenderPackage.useMutation({ onSuccess: refresh });
  const approveRenderPackage = trpc.guidedWreath.approveRenderPackage.useMutation({ onSuccess: refresh });
  const requestManualRenderHandoff = trpc.guidedWreath.requestManualRenderHandoff.useMutation({ onSuccess: refresh });
  const requestRenderRevision = trpc.guidedWreath.requestRenderRevision.useMutation({ onSuccess: () => { setRevisionReason(""); void refresh(); } });
  const [projectName, setProjectName] = useState("A wreath from a memory");
  const [memory, setMemory] = useState("");
  const [visibility, setVisibility] = useState<"private" | "private_story_shareable_wreath" | "private_link_lookbook" | "anonymous_gallery" | "public_first_name" | "fully_public">("private");
  const [manualHandoffNote, setManualHandoffNote] = useState("");
  const [revisionReason, setRevisionReason] = useState("");
  const [comparisonBaselineId, setComparisonBaselineId] = useState<number | undefined>();
  const currentStage = (journey.data?.stageState?.currentStage ?? "memory") as StageKey;
  const [viewingStage, setViewingStage] = useState<StageKey>("memory");
  const renderHistory = journey.data?.revisions?.history ?? [];
  const currentRenderPackageId = journey.data?.render?.renderPackage?.id as number | undefined;
  const defaultBaselineId = renderHistory.find((renderPackage: any) => renderPackage.id !== currentRenderPackageId)?.id as number | undefined;
  const selectedBaselineId = renderHistory.some((renderPackage: any) => renderPackage.id === comparisonBaselineId && renderPackage.id !== currentRenderPackageId) ? comparisonBaselineId : defaultBaselineId;
  const comparisonInput = useMemo(() => ({ workspaceId: workspaceId ?? 0, projectId: projectId ?? 0, primaryPackageId: currentRenderPackageId ?? 0, baselinePackageId: selectedBaselineId ?? 0 }), [workspaceId, projectId, currentRenderPackageId, selectedBaselineId]);
  const renderComparison = trpc.guidedWreath.compareRenderPackages.useQuery(comparisonInput, { enabled: Boolean(workspaceId && projectId && currentRenderPackageId && selectedBaselineId) });

  useEffect(() => { if (journey.data?.memory?.body) setMemory(journey.data.memory.body); }, [journey.data?.memory?.body]);
  useEffect(() => { setViewingStage(currentStage); }, [currentStage]);

  if (loading) return <main className="grid min-h-screen place-items-center bg-[#F6F3EE] text-sm text-[#5E564E]">Opening your private design room…</main>;
  if (!isAuthenticated) return <main className="min-h-screen bg-[#F6F3EE] px-5 py-8 text-[#23211F] sm:px-8"><nav className="mx-auto flex max-w-7xl items-center justify-between"><Link href="/" className="font-serif text-2xl">Evercrafted</Link><Link href="/how-it-works" className="text-sm text-[#5E564E]">How it works</Link></nav><section className="mx-auto grid max-w-7xl gap-12 py-20 lg:grid-cols-[1.1fr_.9fr]"><div><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">Create from a memory</p><h1 className="mt-5 max-w-3xl font-serif text-5xl leading-[.96] tracking-[-.055em] sm:text-7xl">Begin with what you remember.</h1><p className="mt-7 max-w-xl text-lg leading-8 text-[#5E564E]">Your memory begins privately. You review its Essence and Story before Evercrafted offers material direction.</p><Button onClick={startLogin} className="mt-9 h-12 rounded-full bg-[#23211F] px-6 text-white hover:bg-[#50645B]">Continue privately <ArrowRight className="ml-2 h-4 w-4" /></Button></div><aside className="rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-7 sm:p-9"><span className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">Your pace</span>{["Share a memory once", "Recognize what feels true", "Choose material identity by role"].map((item, index) => <div key={item} className="mt-7 flex gap-4"><span className="grid h-7 w-7 shrink-0 place-items-center rounded-full bg-[#E6E0D6] text-xs">0{index + 1}</span><p className="pt-0.5 text-sm leading-6 text-[#5E564E]">{item}</p></div>)}</aside></section></main>;
  if (!projectId) return <main className="min-h-screen bg-[#F6F3EE] px-5 py-8 text-[#23211F] sm:px-8"><nav className="mx-auto flex max-w-6xl items-center justify-between"><Link href="/" className="font-serif text-2xl">Evercrafted</Link><Link href="/app" className="text-sm text-[#5E564E]">My workspace</Link></nav><section className="mx-auto max-w-3xl py-16"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">Create from a memory</p><h1 className="mt-5 font-serif text-5xl tracking-[-.055em]">Give this memory a quiet name.</h1><p className="mt-5 max-w-2xl text-lg leading-8 text-[#5E564E]">This creates a private Evercrafted project in your selected workspace. Nothing is published, commissioned, or shared.</p><div className="mt-10 rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-6 sm:p-9"><label className="block text-sm font-medium" htmlFor="wreath-project-name">Project name</label><Input id="wreath-project-name" value={projectName} onChange={event => setProjectName(event.target.value)} className="mt-3 h-12 border-[#CFC5B8] bg-white text-base" /><p className="mt-3 text-sm text-[#70685F]">Workspace: {spaces.data?.find(space => space.id === workspaceId)?.name ?? "Loading your workspace…"}</p><Button disabled={!workspaceId || start.isPending || projectName.trim().length < 2} onClick={() => workspaceId && start.mutate({ workspaceId, name: projectName })} className="mt-7 h-12 rounded-full bg-[#23211F] px-6 text-white hover:bg-[#50645B]">{start.isPending ? "Opening…" : "Begin privately"}<ArrowRight className="ml-2 h-4 w-4" /></Button>{start.error ? <p role="alert" className="mt-4 text-sm text-red-700">{start.error.message}</p> : null}</div></section></main>;
  if (!workspaceId) return <main className="grid min-h-screen place-items-center bg-[#F6F3EE] text-sm text-[#5E564E]">Loading your authorized workspace…</main>;

  const storyApproved = journey.data?.story?.status === "approved";
  const renderStage = () => {
    if (viewingStage === "memory") return <section className="rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-6 sm:p-9"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">01 · Memory</p><h2 className="mt-4 max-w-2xl font-serif text-4xl tracking-[-.04em]">What should this wreath remember?</h2><p className="mt-4 max-w-2xl text-base leading-7 text-[#5E564E]">Write freely. Your source remains distinct from Evercrafted’s interpretation.</p><label className="mt-7 block text-sm font-medium" htmlFor="memory-body">Your memory</label><Textarea id="memory-body" value={memory} onChange={event => setMemory(event.target.value)} className="mt-3 min-h-56 border-[#CFC5B8] bg-white p-4 text-base leading-7" placeholder="A moment, a person, a place, or a feeling you want to carry forward…" /><label className="mt-5 block text-sm font-medium" htmlFor="memory-visibility">Privacy choice</label><select id="memory-visibility" value={visibility} onChange={event => setVisibility(event.target.value as typeof visibility)} className="mt-2 h-11 w-full max-w-md rounded-md border border-[#CFC5B8] bg-white px-3 text-sm"><option value="private">Completely private</option><option value="private_story_shareable_wreath">Private story, shareable wreath later</option><option value="private_link_lookbook">Private-link Lookbook later</option><option value="anonymous_gallery">Anonymous gallery only later</option><option value="public_first_name">Public with first name later</option><option value="fully_public">Fully public later</option></select><p className="mt-3 text-sm leading-6 text-[#70685F]">Saving a memory does not give permission to publish it.</p><Button disabled={saveMemory.isPending || memory.trim().length < 20} onClick={() => saveMemory.mutate({ workspaceId, projectId, body: memory, visibility })} className="mt-7 h-12 rounded-full bg-[#23211F] px-6 text-white hover:bg-[#50645B]">{saveMemory.isPending ? "Saving privately…" : "Save memory"}<ArrowRight className="ml-2 h-4 w-4" /></Button>{saveMemory.error ? <p role="alert" className="mt-4 text-sm text-red-700">{saveMemory.error.message}</p> : null}</section>;
    if (viewingStage === "essence") return <section className="rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-6 sm:p-9"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">02 · Your Essence</p>{!journey.data?.memory ? <><h2 className="mt-4 font-serif text-4xl">Your memory comes first.</h2><p className="mt-4 text-[#5E564E]">Save your memory before Evercrafted offers an interpretation.</p></> : !journey.data?.essence ? <><h2 className="mt-4 max-w-2xl font-serif text-4xl tracking-[-.04em]">Let us offer a draft for you to recognize or correct.</h2><p className="mt-4 text-[#5E564E]">The draft is grounded in your saved words. It is never a substitute for what feels true to you.</p><Button disabled={generateDraft.isPending} onClick={() => generateDraft.mutate({ workspaceId, projectId })} className="mt-7 h-12 rounded-full bg-[#23211F] px-6 text-white hover:bg-[#50645B]">{generateDraft.isPending ? "Preparing your draft…" : "Create Your Essence draft"}<Sparkles className="ml-2 h-4 w-4" /></Button></> : <><h2 className="mt-4 font-serif text-4xl tracking-[-.04em]">Does this feel true?</h2><div className="mt-7 grid gap-3 sm:grid-cols-2">{[["Emotional center", journey.data.essence.emotionalCenter], ["Atmosphere", journey.data.essence.atmosphere], ["Movement", journey.data.essence.movement], ["Palette direction", journey.data.essence.paletteDirection], ["Visual tension", journey.data.essence.visualTension]].map(([label, value]) => <div key={label} className="rounded-2xl bg-[#F2EEE7] p-4"><p className="text-xs font-semibold uppercase tracking-[.13em] text-[#6B5A4A]">{label}</p><p className="mt-2 text-sm leading-6 text-[#423D38]">{value}</p></div>)}</div><p className="mt-6 max-w-2xl text-base leading-7 text-[#5E564E]">{journey.data.essence.expression}</p>{Array.isArray(journey.data.essence.unsupportedClaims) && journey.data.essence.unsupportedClaims.length ? <div role="alert" className="mt-6 rounded-2xl border border-[#D8BDA4] bg-[#FFF8ED] p-4 text-sm leading-6 text-[#7B4A22]"><strong>Review needed.</strong> {journey.data.essence.unsupportedClaims.join(" ")}</div> : null}<Button disabled={decide.isPending || Boolean((journey.data.essence.unsupportedClaims as unknown[])?.length)} onClick={() => decide.mutate({ workspaceId, projectId, stage: "essence", entityId: journey.data.essence.id, decision: "approved" })} className="mt-7 h-11 rounded-full bg-[#23211F] px-5 text-white hover:bg-[#50645B]">This feels true <Check className="ml-2 h-4 w-4" /></Button></>}</section>;
    if (viewingStage === "story") return <section className="rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-6 sm:p-9"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">03 · Memory Story</p>{!journey.data?.story ? <><h2 className="mt-4 font-serif text-4xl">Your Story follows Your Essence.</h2><p className="mt-4 text-[#5E564E]">Approve the Essence first. The Story never selects flowers or wreath construction.</p></> : <><h2 className="mt-4 max-w-2xl font-serif text-4xl tracking-[-.04em]">{journey.data.story.excerpt}</h2><p className="mt-7 max-w-3xl whitespace-pre-wrap text-base leading-8 text-[#4D4741]">{journey.data.story.body}</p><div className="mt-8 rounded-2xl bg-[#F2EEE7] p-5"><p className="text-xs font-semibold uppercase tracking-[.14em] text-[#6B5A4A]">Design signals for later review</p><div className="mt-4 grid gap-3 sm:grid-cols-2">{Object.entries(journey.data.story.designSignals as Record<string, unknown>).slice(0, 6).map(([key, value]) => <div key={key}><p className="text-xs capitalize text-[#70685F]">{key.replace(/[A-Z]/g, letter => ` ${letter.toLowerCase()}`)}</p><p className="mt-1 text-sm text-[#423D38]">{Array.isArray(value) ? value.join(", ") : String(value)}</p></div>)}</div></div><Button disabled={decide.isPending || Boolean((journey.data.story.unsupportedClaims as unknown[])?.length)} onClick={() => decide.mutate({ workspaceId, projectId, stage: "story", entityId: journey.data.story.id, decision: "approved" })} className="mt-7 h-11 rounded-full bg-[#23211F] px-5 text-white hover:bg-[#50645B]">Approve Story <Check className="ml-2 h-4 w-4" /></Button></>}</section>;
    if (viewingStage === "florals") return <FloralStage florals={journey.data?.florals} storyApproved={storyApproved} workspaceId={workspaceId} projectId={projectId} generate={generateFlorals} select={selectFloral} />;
    if (viewingStage === "recipe") return <RecipeStage florals={journey.data?.florals} recipeData={journey.data?.recipe} workspaceId={workspaceId} projectId={projectId} lock={lockRecipe} onBlueprint={() => setViewingStage("blueprint")} />;
    if (viewingStage === "blueprint") return <BlueprintStage recipeData={journey.data?.recipe} workspaceId={workspaceId} projectId={projectId} generate={generateBlueprint} />;
    if (viewingStage === "wreath") return <><RenderPackageStage recipeData={journey.data?.recipe} renderData={journey.data?.render} workspaceId={workspaceId} projectId={projectId} prepare={prepareRenderPackage} approve={approveRenderPackage} requestHandoff={requestManualRenderHandoff} handoffNote={manualHandoffNote} setHandoffNote={setManualHandoffNote} /><RevisionSupport renderData={journey.data?.render} revisionData={journey.data?.revisions} comparison={renderComparison} baselineId={selectedBaselineId} setBaselineId={setComparisonBaselineId} requestRevision={requestRenderRevision} revisionReason={revisionReason} setRevisionReason={setRevisionReason} /></>;
    return <LockedStage stage={viewingStage} />;
  };

  return <main className="min-h-screen bg-[#F6F3EE] px-4 py-5 text-[#23211F] sm:px-7 sm:py-7"><nav className="mx-auto flex max-w-7xl items-center justify-between"><Link href="/" className="font-serif text-2xl">Evercrafted</Link><div className="flex items-center gap-4"><span className="hidden text-sm text-[#70685F] sm:block">Private Wreath Creation</span><Link href="/app" className="text-sm text-[#5E564E] hover:text-[#23211F]">Workspace</Link></div></nav><div className="mx-auto max-w-7xl py-7 sm:py-10">{journey.isLoading ? <p className="py-20 text-center text-sm text-[#70685F]">Opening your saved design journey…</p> : journey.error ? <p role="alert" className="py-20 text-center text-sm text-red-700">{journey.error.message}</p> : <><header className="grid gap-6 border-b border-[#DCD4C9] pb-8 lg:grid-cols-[1fr_auto]"><div><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">Guided Wreath Creation</p><h1 className="mt-3 font-serif text-4xl tracking-[-.045em] sm:text-5xl">{journey.data?.project.name}</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-[#5E564E]">A memory-led design journey. Source, interpretation, role choices, Recipe, and Blueprint remain distinct.</p></div><div className="rounded-2xl border border-[#DCD4C9] bg-[#FFFEFB] px-4 py-3 text-sm text-[#5E564E]"><span className="font-medium text-[#23211F]">Current checkpoint:</span> {stages.find(stage => stage.key === currentStage)?.label}</div></header><div className="mt-7"><StageRail current={currentStage} viewing={viewingStage} onSelect={setViewingStage} /></div>{journey.data?.stageState?.blockReason ? <div className="mt-6 flex items-start gap-3 rounded-2xl border border-[#DDD1BF] bg-[#FFF8ED] p-4 text-sm leading-6 text-[#6B5A4A]"><CircleHelp className="mt-0.5 h-4 w-4 shrink-0" />{journey.data.stageState.blockReason}</div> : null}<div className="mt-8 grid gap-7 lg:grid-cols-[minmax(0,1fr)_280px]"><div>{renderStage()}</div><aside className="rounded-[2rem] border border-[#DED7CC] bg-[#FFFEFB] p-5 sm:p-6"><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#6B5A4A]">Memory Thread</p><p className="mt-3 text-sm leading-6 text-[#70685F]">Each point remains connected to its source version.</p><div className="mt-6 space-y-5">{journey.data?.thread.length ? journey.data.thread.map(event => <div key={event.id} className="border-l border-[#BEB3A4] pl-4"><p className="text-xs font-semibold uppercase tracking-[.12em] text-[#6B5A4A]">{event.stage}</p><p className="mt-1 text-sm leading-5 text-[#423D38]">{event.summary}</p><span className="mt-2 inline-block text-xs text-[#70685F]">{event.isDirectSource ? "Direct source" : "Interpretation for review"}</span></div>) : <p className="text-sm leading-6 text-[#70685F]">Your saved memory appears here as the first source node.</p>}</div></aside></div></>}</div></main>;
}
